import { useState } from 'react';
import { Alert, Avatar, Box, Button, ButtonGroup, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, Divider, FormControl, IconButton, InputAdornment, MenuItem, Select, Stack, Tab, Tabs, Table, TableBody, TableCell, TableHead, TableRow, TableSortLabel, TextField, Tooltip, Typography, useTheme } from '@mui/material';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import MoreHorizIcon from '@mui/icons-material/MoreHoriz';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import MailOutlineIcon from '@mui/icons-material/MailOutline';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import ShareOutlinedIcon from '@mui/icons-material/ShareOutlined';
import DownloadIcon from '@mui/icons-material/Download';
import StarBorderIcon from '@mui/icons-material/StarBorder';
import StarIcon from '@mui/icons-material/Star';
import { CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from 'recharts';
import { tokens } from '../theme/theme';
import type { AuditEntry, CalendarEvent, CRMData, Deal, EmailItem, Invoice, Lead, Stage, Task, TeamUser, Ticket } from './types';
import { formatMoney, Metric, PageTitle, Panel, PriorityChip, StageChip, UserAvatar } from './ui';

const trend = [{month:'May',won:24,lost:14},{month:'Jun',won:32,lost:16},{month:'Jul',won:28,lost:21},{month:'Aug',won:45,lost:19},{month:'Sep',won:39,lost:24},{month:'Oct',won:58,lost:26}];
const sourceData = [{name:'Website',value:15,color:'#3B82F6'},{name:'Referral',value:10,color:'#16A34A'},{name:'LinkedIn',value:8,color:'#7C3AED'},{name:'Cold Call',value:5,color:'#F59E0B'},{name:'Other',value:4,color:'#94A3B8'}];
const stageTotals:Record<string,{count:number;amount:number}>={New:{count:8,amount:72000},Contacted:{count:11,amount:68000},Qualified:{count:9,amount:84500},Proposal:{count:7,amount:62000},Won:{count:7,amount:56000}};
const stages:Stage[]=['New','Contacted','Qualified','Proposal','Won'];

export function Dashboard({ data, onNavigate }: { data:CRMData; onNavigate:(s:string)=>void }) {
  const [selectedStage,setSelectedStage]=useState<string|null>(null);
  const [selectedDeal,setSelectedDeal]=useState<Deal|null>(null);
  const [selectedActivity,setSelectedActivity]=useState<{id:string;title:string;detail:string;time:string;date:string;type:string;source:string}|null>(null);
  const [activityOpen,setActivityOpen]=useState(false);
  const [activityPeriod,setActivityPeriod]=useState<'Day'|'Week'|'Month'>('Day');
  // The mockup gives workspace-wide totals, while the local fixture includes only named example records.
  const sampleDeals=data.deals;
  const aggregateDeals=(stage:string)=>sampleDeals.filter(deal=>deal.stage===stage);
  const currentOpenDeals=sampleDeals.filter(deal=>deal.stage!=='Won'&&deal.stage!=='Lost').length;
  const openDealCount=Math.max(0,42+(currentOpenDeals-12));
  const leadCount=248+Math.max(0,data.leads.length-7);
  const sampleOpenAmount=sampleDeals.filter(deal=>deal.stage!=='Won'&&deal.stage!=='Lost').reduce((sum,deal)=>sum+deal.amount,0);
  const openAmount=284600+(sampleOpenAmount-129000);
  const colors=['#3B82F6','#0891B2','#7C3AED','#F59E0B','#16A34A'];
  const stageRows=Object.entries(stageTotals).map(([name,baseline],index)=>{
    const visible=aggregateDeals(name);
    return {name,value:Math.max(0,baseline.count+(visible.length-3)),color:colors[index],records:visible};
  });
  // Activities stay tied to the seeded calendar and task records, with the reference date as the default day.
  const activities=[
    ...data.events.map(event=>({id:event.id,title:event.title,date:event.date,time:event.time,type:event.kind,detail:`${event.kind} · ${event.duration} minutes`,source:'Calendar'})),
    ...data.tasks.map(task=>({id:task.id,title:task.title,date:task.due.slice(0,10),time:task.due.slice(11,16),type:'Task',detail:`${task.priority} priority · ${task.status}`,source:'Tasks'})),
    ...data.leads.flatMap(lead=>lead.activity.map((entry,index)=>{const parsed=new Date(entry.time);const valid=Number.isNaN(parsed.getTime())?new Date('2026-10-21T12:00:00'):parsed;return{id:`${lead.id}-activity-${index}`,title:entry.title,date:valid.toISOString().slice(0,10),time:entry.time,type:'Lead',detail:`${lead.name} · ${entry.detail}`,source:'Leads'};})),
  ].sort((a,b)=>`${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`));
  const day=new Date().toISOString().slice(0,10);
  const weekStart=new Date(`${day}T00:00:00`);weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const weekEnd=new Date(weekStart);weekEnd.setDate(weekEnd.getDate()+6);
  const visibleActivities=activities.filter(item=>{const date=new Date(`${item.date}T00:00:00`);return activityPeriod==='Day'?item.date===day:activityPeriod==='Week'?date>=weekStart&&date<=weekEnd:item.date.startsWith(day.slice(0,7));});
  const currentStage=stageRows.find(stage=>stage.name===selectedStage);
  const metrics=[
    {label:'Total Leads',value:String(leadCount),delta:'12% vs last week',screen:'Leads'},
    {label:'Active Deals',value:String(openDealCount),delta:'8% vs last week',screen:'Deals'},
    {label:'Revenue Pipeline',value:formatMoney(openAmount),delta:'15% vs last week',screen:'Deals'},
    {label:'Conversion Rate',value:'16.9%',delta:'2.4% vs last week',screen:'Reports'},
  ];
  return <>
    <Box sx={{p:2.5,mb:2.5,borderRadius:3,color:'#fff',background:'linear-gradient(105deg,#10244F 0%,#1D4ED8 65%,#3B82F6 100%)',display:'flex',justifyContent:'space-between',alignItems:'center'}}><Box><Typography variant="h2" color="inherit">Good morning, Dinesh!</Typography><Typography sx={{color:'#DCE7FF'}}>Here's what's happening with your sales today.</Typography></Box><Typography fontWeight={600} sx={{display:{xs:'none',sm:'block'}}}>Big goals. Better tools.</Typography></Box>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'repeat(2,minmax(0,1fr))',xl:'repeat(4,minmax(0,1fr))'},gap:1.5,mb:2.5}}>{metrics.map(metric=><Metric key={metric.label} {...metric} onClick={()=>onNavigate(metric.screen)}/>)}</Box>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'1.45fr 1.15fr 1fr'},gap:1.5}}>
      <Panel sx={{minHeight:350}}><Typography variant="h3" sx={{mb:2}}>Sales Pipeline Trend</Typography><ResponsiveContainer width="100%" height={275}><LineChart data={trend} margin={{left:-18,right:10,top:8,bottom:0}}><CartesianGrid stroke="#E8EDF4" vertical={false}/><XAxis dataKey="month" tickLine={false} axisLine={false}/><YAxis tickLine={false} axisLine={false}/><ChartTooltip/><Line type="monotone" dataKey="won" stroke={tokens.primary500} strokeWidth={3} dot={false}/><Line type="monotone" dataKey="lost" stroke={tokens.danger} strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer><Stack direction="row" justifyContent="center" gap={2}><Typography variant="caption" color="primary">● Won</Typography><Typography variant="caption" color="error">● Lost</Typography></Stack></Panel>
      <Panel sx={{minHeight:350}}><Typography variant="h3" sx={{mb:1}}>Deals by Stage</Typography><Box sx={{height:260,position:'relative'}}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={stageRows} dataKey="value" innerRadius={62} outerRadius={95} paddingAngle={3} onClick={entry=>setSelectedStage(entry.name)}>{stageRows.map((stage)=><Cell key={stage.name} fill={stage.color} cursor="pointer" onClick={()=>setSelectedStage(stage.name)}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer><Box sx={{position:'absolute',inset:0,display:'grid',placeContent:'center',textAlign:'center',pointerEvents:'none'}}><Typography fontSize={26} fontWeight={700}>{openDealCount}</Typography><Typography variant="caption" color="text.secondary">Total</Typography></Box></Box><Stack spacing={.6}>{stageRows.map(stage=><Button key={stage.name} onClick={()=>setSelectedStage(stage.name)} aria-label={`View ${stage.value} ${stage.name} deals`} sx={{justifyContent:'flex-start',minHeight:28,py:.25,px:.5,textTransform:'none',color:'text.primary'}}><Box sx={{width:8,height:8,borderRadius:9,bgcolor:stage.color,mr:1}}/><Typography variant="body2" sx={{flex:1,textAlign:'left'}}>{stage.name}</Typography><Typography variant="body2" fontWeight={600}>{stage.value}</Typography></Button>)}</Stack></Panel>
      <Panel sx={{minHeight:350}}><Typography variant="h3" sx={{mb:2}}>Recent Activities</Typography><Stack spacing={1}>{activities.filter(item=>item.date===day).slice(-4).reverse().map(item=><Button key={`${item.source}-${item.id}`} onClick={()=>setSelectedActivity(item)} sx={{p:.75,justifyContent:'flex-start',textAlign:'left',textTransform:'none',color:'text.primary'}}><Avatar sx={{width:32,height:32,mr:1.25,bgcolor:'action.selected',color:'primary.main',fontSize:12,fontWeight:700}}>{item.type[0]}</Avatar><Box sx={{minWidth:0}}><Typography noWrap fontWeight={600}>{item.title}</Typography><Typography variant="body2" color="text.secondary">{item.time} · {item.detail}</Typography></Box></Button>)}{!activities.some(item=>item.date===day)&&<Typography color="text.secondary">No activity recorded today.</Typography>}</Stack><Stack direction="row" gap={1} sx={{mt:1.5}}><Button onClick={()=>onNavigate('Calendar')}>View calendar</Button><Button onClick={()=>setActivityOpen(true)}>See all</Button></Stack></Panel>
    </Box>
    <Dialog open={Boolean(currentStage)} onClose={()=>setSelectedStage(null)} fullWidth maxWidth="sm"><DialogTitle>{currentStage?.name} deals · {currentStage?.value}</DialogTitle><DialogContent dividers>{currentStage?.records.length?<Stack spacing={1}>{currentStage.records.map(deal=><Button key={deal.id} onClick={()=>setSelectedDeal(deal)} sx={{p:1.25,justifyContent:'stretch',textAlign:'left',textTransform:'none',color:'text.primary',border:`1px solid ${tokens.border}`,borderRadius:2}}><Stack direction="row" justifyContent="space-between" gap={1} width="100%"><Typography fontWeight={600}>{deal.company}</Typography><Typography>{formatMoney(deal.amount)}</Typography></Stack><Typography variant="body2" color="text.secondary">{deal.title} · {deal.owner} · {deal.probability}% probability</Typography></Button>)}</Stack>:<Alert severity="info">The reference shows {currentStage?.value} deals in this stage. The browser demo includes no named sample records for this stage.</Alert>}{currentStage&&currentStage.records.length<currentStage.value&&<Typography variant="caption" color="text.secondary" display="block" sx={{mt:1}}>Showing {currentStage.records.length} named sample records; the remaining records are part of the reference aggregate.</Typography>}</DialogContent><DialogActions><Button onClick={()=>{setSelectedStage(null);onNavigate('Deals');}}>Open Deals</Button><Button onClick={()=>setSelectedStage(null)}>Close</Button></DialogActions></Dialog>
    <Dialog open={activityOpen} onClose={()=>setActivityOpen(false)} fullWidth maxWidth="md"><DialogTitle>Activities</DialogTitle><DialogContent dividers><Stack direction="row" gap={1} sx={{mb:1.5}}><ButtonGroup size="small">{(['Day','Week','Month'] as const).map(period=><Button key={period} variant={activityPeriod===period?'contained':'outlined'} onClick={()=>setActivityPeriod(period)}>{period}</Button>)}</ButtonGroup><Typography variant="body2" color="text.secondary" sx={{alignSelf:'center'}}>{new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}</Typography></Stack>{visibleActivities.length?<Stack spacing={.75}>{visibleActivities.map(item=><Button key={`${item.source}-${item.id}`} onClick={()=>setSelectedActivity(item)} sx={{p:1.25,justifyContent:'space-between',textTransform:'none',textAlign:'left',border:`1px solid ${tokens.border}`,borderRadius:2,color:'text.primary'}}><Box><Typography fontWeight={600}>{item.title}</Typography><Typography variant="body2" color="text.secondary">{item.detail}</Typography></Box><Typography variant="body2" color="text.secondary">{item.date} · {item.time}</Typography></Button>)}</Stack>:<Alert severity="info">No activities are recorded for this period.</Alert>}</DialogContent><DialogActions><Button onClick={()=>setActivityOpen(false)}>Close</Button></DialogActions></Dialog>
    <Dialog open={Boolean(selectedActivity)} onClose={()=>setSelectedActivity(null)} fullWidth maxWidth="xs"><DialogTitle>{selectedActivity?.title}</DialogTitle><DialogContent dividers><Typography color="text.secondary">{selectedActivity?.detail}</Typography><Stack spacing={.75} sx={{mt:1.5}}><Typography><b>Type:</b> {selectedActivity?.type}</Typography><Typography><b>Date:</b> {selectedActivity?.date}</Typography><Typography><b>Time:</b> {selectedActivity?.time}</Typography><Typography><b>Record:</b> {selectedActivity?.source}</Typography></Stack></DialogContent><DialogActions><Button onClick={()=>setSelectedActivity(null)}>Close</Button><Button onClick={()=>{const target=selectedActivity?.source;setSelectedActivity(null);if(target)onNavigate(target);}}>Open record</Button></DialogActions></Dialog>
    <Dialog open={Boolean(selectedDeal)} onClose={()=>setSelectedDeal(null)} fullWidth maxWidth="xs"><DialogTitle>Deal details</DialogTitle><DialogContent dividers>{selectedDeal&&<Stack spacing={.75}><Typography variant="h3">{selectedDeal.title}</Typography><Typography color="text.secondary">{selectedDeal.company}</Typography><Divider sx={{my:1}}/><Typography><b>Amount:</b> {formatMoney(selectedDeal.amount)}</Typography><Typography><b>Stage:</b> {selectedDeal.stage}</Typography><Typography><b>Owner:</b> {selectedDeal.owner}</Typography><Typography><b>Probability:</b> {selectedDeal.probability}%</Typography><Typography><b>Expected close:</b> {selectedDeal.closeDate}</Typography></Stack>}</DialogContent><DialogActions><Button onClick={()=>setSelectedDeal(null)}>Close</Button><Button onClick={()=>{setSelectedDeal(null);onNavigate('Deals');}}>Open deals board</Button></DialogActions></Dialog>
  </>;
}

export function TasksScreen({tasks,onAdd,onToggle,onEdit}:{tasks:Task[];onAdd:()=>void;onToggle:(id:string)=>void;onEdit:(t:Task)=>void}) {
  const [tab,setTab]=useState('Today'); const [selected,setSelected]=useState(tasks[0]?.id??'');
  const today=tasks.filter(t=>t.due>='2026-10-21'&&t.due<'2026-10-25'); const upcoming=tasks.filter(t=>t.due>='2026-10-25'&&t.status!=='Done'); const overdue=tasks.filter(t=>t.due<'2026-10-21'&&t.status!=='Done');
  const rows=tab==='Today'?today:tab==='Upcoming'?upcoming:overdue; const current=tasks.find(t=>t.id===selected)??rows[0]; const upcomingCount=12+upcoming.length;const overdueCount=3+overdue.length;
  return <><PageTitle title="My Tasks" actions={<Button variant="contained" startIcon={<AddIcon/>} onClick={onAdd}>Add Task</Button>}/><Tabs value={tab} onChange={(_,v)=>setTab(v)} sx={{mb:1.5}}>{[['Today',today.length],['Upcoming',upcomingCount],['Overdue',overdueCount]].map(([x,n])=><Tab key={x as string} value={x} label={`${x} (${n})`}/>)}</Tabs>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'1.6fr 1fr'},gap:1.5}}><Panel sx={{p:0,overflow:'hidden'}}><Box sx={{overflowX:'auto'}}><Table size="small" sx={{minWidth:620}}><TableHead><TableRow>{['','Task','Priority','Due Date','Status'].map(x=><TableCell key={x} sx={{fontWeight:600,color:'text.secondary'}}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{rows.map(t=><TableRow key={t.id} hover selected={t.id===current?.id} onClick={()=>setSelected(t.id)} sx={{cursor:'pointer'}}><TableCell padding="checkbox"><Checkbox checked={t.status==='Done'} size="small" onClick={e=>e.stopPropagation()} onChange={()=>onToggle(t.id)}/></TableCell><TableCell>{t.title}</TableCell><TableCell><PriorityChip priority={t.priority}/></TableCell><TableCell>{new Date(t.due).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</TableCell><TableCell><Chip size="small" label={t.status} color={t.status==='Done'?'success':t.status==='In Progress'?'primary':'warning'} sx={{fontWeight:600}}/></TableCell></TableRow>)}</TableBody></Table></Box><Box sx={{p:2}}><Typography variant="body2" color="text.secondary">{rows.length} tasks · Select a task to view details</Typography></Box></Panel>
      {current&&<Panel><Typography variant="h3">Task Details</Typography><Typography fontWeight={700} sx={{mt:1}}>{current.title}</Typography><Typography color="text.secondary" sx={{mt:.5}}>{current.detail}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1.5}}>Related to</Typography><Typography>{current.related}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1.25}}>Assigned to</Typography><Typography>{current.assignee}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1.25}}>Due date</Typography><Typography>{new Date(current.due).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'})}</Typography><Stack direction="row" gap={1} sx={{mt:2}}><Button variant="contained" color={current.status==='Done'?'inherit':'success'} fullWidth onClick={()=>onToggle(current.id)}>{current.status==='Done'?'Reopen task':'Mark Complete'}</Button><Button variant="outlined" onClick={()=>onEdit(current)}>Edit</Button></Stack></Panel>}</Box>
  </>;
}

export function CalendarScreen({events,onAdd,onSelect,onDelete}:{events:CalendarEvent[];onAdd:()=>void;onSelect:(e:CalendarEvent)=>void;onDelete:(id:string)=>void}) {
  const [view,setView]=useState('Week'); const [offset,setOffset]=useState(0); const [selected,setSelected]=useState('2026-10-21');const [selectedEvent,setSelectedEvent]=useState<CalendarEvent|null>(null); const base=view==='Month'?new Date(2026,9+offset,1):new Date(2026,9,19+offset*7); const weekStart=new Date(2026,9,19+offset*7); const days=view==='Day'?[new Date(`${selected}T00:00:00`)]:Array.from({length:5},(_,i)=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);return d});
  const theme=useTheme();const dark=theme.palette.mode==='dark';const hh=Array.from({length:10},(_,i)=>i+8); const fmt=(d:Date)=>d.toISOString().slice(0,10); const colors:Record<CalendarEvent['kind'],string>=dark?{Meeting:'#1E3A5F',Call:'#51400C',Task:'#36215C',Personal:'#4A2440'}:{Meeting:'#DBEAFE',Call:'#FEF3C7',Task:'#EDE9FE',Personal:'#FCE7F3'};
  return <><PageTitle title="Calendar" actions={<Button variant="contained" startIcon={<AddIcon/>} onClick={onAdd}>Add Event</Button>}/>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',md:'260px 1fr'},gap:1.5}}><Panel><Stack direction="row" alignItems="center" justifyContent="space-between"><IconButton onClick={()=>setOffset(o=>o-1)}>‹</IconButton><Typography variant="h3">{base.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</Typography><IconButton onClick={()=>setOffset(o=>o+1)}>›</IconButton></Stack><Box sx={{display:'grid',gridTemplateColumns:'repeat(7,1fr)',mt:1}}>{['S','M','T','W','T','F','S'].map((d,i)=><Typography key={d+i} variant="caption" textAlign="center" color="text.secondary">{d}</Typography>)}{Array.from({length:35},(_,i)=>{const day=i-3+1;const date=new Date(base.getFullYear(),base.getMonth(),day);const iso=fmt(date);return <Button key={i} size="small" onClick={()=>setSelected(iso)} sx={{minWidth:0,minHeight:34,p:0,borderRadius:99,bgcolor:iso===selected?tokens.primary600:'transparent',color:iso===selected?'white':'text.primary'}}>{date.getDate()}</Button>})}</Box><Divider sx={{my:1.5}}/><Typography variant="h3" sx={{mb:1}}>My Calendars</Typography>{(['Meeting','Call','Task','Personal'] as const).map((x,i)=><Stack key={x} direction="row" alignItems="center"><Checkbox defaultChecked size="small" sx={{p:.5}}/><Typography>{x}s</Typography><Box sx={{ml:'auto',width:10,height:10,borderRadius:99,bgcolor:Object.values(colors)[i]}}/></Stack>)}</Panel>
      <Panel sx={{p:1.5,overflow:'hidden'}}><Stack direction="row" alignItems="center" justifyContent="space-between" sx={{mb:1}}><Stack direction="row" alignItems="center" gap={1}><Button onClick={()=>setOffset(o=>o-1)}>‹</Button><Typography variant="h3">{base.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</Typography><Button onClick={()=>setOffset(o=>o+1)}>›</Button></Stack><ButtonGroup size="small">{['Day','Week','Month'].map(v=><Button key={v} variant={view===v?'contained':'outlined'} onClick={()=>setView(v)}>{v}</Button>)}</ButtonGroup></Stack>{view==='Month'?<Box sx={{display:'grid',gridTemplateColumns:'repeat(7,minmax(70px,1fr))',overflowX:'auto'}}>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=><Typography key={x} variant="caption" textAlign="center" sx={{p:1,color:'text.secondary'}}>{x}</Typography>)}{Array.from({length:35},(_,i)=>{const first=new Date(base.getFullYear(),base.getMonth(),1);const date=new Date(first);date.setDate(1-first.getDay()+i);const iso=fmt(date);return <Box key={iso} onClick={()=>setSelected(iso)} sx={{minHeight:95,p:.5,borderTop:`1px solid ${tokens.border}`,borderLeft:`1px solid ${tokens.border}`,bgcolor:date.getMonth()===base.getMonth()?'background.paper':'action.hover',cursor:'pointer'}}><Typography variant="caption" color={iso===selected?'primary.main':'text.secondary'} fontWeight={iso===selected?700:400}>{date.getDate()}</Typography>{events.filter(e=>e.date===iso).map(e=><Box key={e.id} onClick={ev=>{ev.stopPropagation();setSelectedEvent(e)}} sx={{mt:.25,p:.25,px:.5,bgcolor:colors[e.kind],color:dark?'text.primary':'#172033',borderRadius:.5,fontSize:10,overflow:'hidden',whiteSpace:'nowrap',textOverflow:'ellipsis'}}>{e.time} {e.title}</Box>)}</Box>})}</Box>:<Box sx={{overflowX:'auto'}}><Box sx={{display:'grid',gridTemplateColumns:`60px repeat(${days.length},minmax(90px,1fr))`,minWidth:500}}><Box/>{days.map(d=><Box key={d.toString()} onClick={()=>setSelected(fmt(d))} sx={{textAlign:'center',p:1,borderBottom:`2px solid ${fmt(d)===selected?tokens.primary600:tokens.border}`,color:fmt(d)===selected?'primary.main':'text.primary',cursor:'pointer'}}><Typography variant="caption">{d.toLocaleDateString('en-US',{weekday:'short'})}</Typography><Typography fontWeight={700}>{d.getDate()}</Typography></Box>)}{hh.map(hour=><Box key={hour} sx={{display:'contents'}}><Box sx={{height:66,borderBottom:`1px solid ${tokens.border}`,pt:.5}}><Typography variant="caption" color="text.secondary">{hour%12||12} {hour<12?'AM':'PM'}</Typography></Box>{days.map(d=>{const ev=events.filter(e=>e.date===fmt(d)&&Number(e.time.slice(0,2))===hour);return <Box key={fmt(d)} sx={{height:66,borderBottom:`1px solid ${tokens.border}`,borderLeft:`1px solid ${tokens.border}`,p:.25}}>{ev.map(e=><Box key={e.id} onClick={()=>setSelectedEvent(e)} sx={{p:.75,bgcolor:colors[e.kind],color:dark?'text.primary':'#172033',borderLeft:`3px solid ${tokens.primary600}`,borderRadius:1,cursor:'pointer',fontSize:12,fontWeight:600}}>{e.title}<Typography variant="caption" display="block">{e.time}</Typography></Box>)}</Box>})}</Box>)}</Box></Box>}</Panel></Box>
    <Stack direction="row" flexWrap="wrap" gap={1} sx={{mt:1.5}}>{events.filter(e=>e.date===selected).map(e=><Chip key={e.id} label={`${e.time} · ${e.title}`} onClick={()=>setSelectedEvent(e)} onDelete={()=>onDelete(e.id)} sx={{bgcolor:colors[e.kind],color:dark?'text.primary':'#172033'}}/>)}{!events.some(e=>e.date===selected)&&<Typography color="text.secondary">No events for this date.</Typography>}</Stack>
    <Dialog open={Boolean(selectedEvent)} onClose={()=>setSelectedEvent(null)} fullWidth maxWidth="xs"><DialogTitle>{selectedEvent?.title}</DialogTitle><DialogContent dividers>{selectedEvent&&<Stack spacing={.75}><Typography color="text.secondary">Calendar event details</Typography><Typography><b>Type:</b> {selectedEvent.kind}</Typography><Typography><b>Date:</b> {new Date(`${selectedEvent.date}T00:00:00`).toLocaleDateString()}</Typography><Typography><b>Time:</b> {selectedEvent.time}</Typography><Typography><b>Duration:</b> {selectedEvent.duration} minutes</Typography></Stack>}</DialogContent><DialogActions><Button color="error" onClick={()=>{if(selectedEvent)onDelete(selectedEvent.id);setSelectedEvent(null);}}>Delete</Button><Button onClick={()=>setSelectedEvent(null)}>Close</Button><Button variant="contained" onClick={()=>{if(selectedEvent)onSelect(selectedEvent);setSelectedEvent(null);}}>Edit event</Button></DialogActions></Dialog>
  </>;
}

export function EmailScreen({emails,onCompose,onDraft,onSelect}:{emails:EmailItem[];onCompose:()=>void;onDraft:(to:string,subject:string)=>void;onSelect:(m:EmailItem)=>void}) {
  const [folder,setFolder]=useState('Inbox');const [selected,setSelected]=useState(emails[0]?.id??'');const [starred,setStarred]=useState<string[]>([]);const [important,setImportant]=useState<string[]>([]);const [archived,setArchived]=useState<string[]>([]);const current=emails.find(m=>m.id===selected);const folders=['Inbox','Sent','Drafts','Starred','Important','Archived'];
  const visible=emails.filter(m=>folder==='Inbox'?m.folder==='Inbox'&&!archived.includes(m.id):folder==='Sent'?m.folder==='Sent':folder==='Drafts'?m.folder==='Drafts':folder==='Starred'?starred.includes(m.id):folder==='Important'?important.includes(m.id):archived.includes(m.id));
  return <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',md:'220px minmax(250px,1fr) 1.4fr'},gap:1.5,minHeight:650}}><Panel><Button fullWidth variant="contained" onClick={onCompose}>Compose</Button><Stack sx={{mt:1}}>{folders.map(f=><Button key={f} onClick={()=>setFolder(f)} variant={folder===f?'contained':'text'} color={folder===f?'primary':'inherit'} sx={{justifyContent:'flex-start'}}>{f}{f==='Inbox'&&<Chip size="small" label="12" sx={{ml:'auto',height:20}}/>}</Button>)}</Stack></Panel>
    <Panel sx={{p:0,overflow:'hidden'}}><Box sx={{p:1.5,borderBottom:`1px solid ${tokens.border}`}}><Typography variant="h3">{folder}</Typography></Box>{visible.map(m=><Box key={m.id} onClick={()=>{setSelected(m.id);onSelect(m)}} sx={{p:1.5,borderBottom:`1px solid ${tokens.border}`,bgcolor:m.id===selected?'action.selected':'background.paper',cursor:'pointer'}}><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography fontWeight={m.unread?700:500}>{m.from}</Typography><Stack direction="row" alignItems="center"><Typography variant="caption" color="text.secondary">{m.date}</Typography><IconButton size="small" aria-label={starred.includes(m.id)?'Unstar':'Star'} onClick={e=>{e.stopPropagation();setStarred(s=>s.includes(m.id)?s.filter(x=>x!==m.id):[...s,m.id]);}}>{starred.includes(m.id)?<StarIcon fontSize="small" color="warning"/>:<StarBorderIcon fontSize="small"/>}</IconButton><IconButton size="small" aria-label="Mark important" onClick={e=>{e.stopPropagation();setImportant(s=>s.includes(m.id)?s.filter(x=>x!==m.id):[...s,m.id]);}}><Typography color={important.includes(m.id)?'warning.main':'text.disabled'} fontWeight={800}>!</Typography></IconButton><IconButton size="small" aria-label="Archive email" onClick={e=>{e.stopPropagation();setArchived(s=>[...s,m.id]);}}><MoreHorizIcon fontSize="small"/></IconButton></Stack></Stack><Typography variant="body2" fontWeight={600}>{m.subject}</Typography><Typography variant="body2" color="text.secondary" noWrap>{m.preview}</Typography></Box>)}{visible.length===0&&<Typography color="text.secondary" sx={{p:2}}>No messages in {folder.toLowerCase()}.</Typography>}</Panel>
    <Panel>{current?<><Typography variant="h2">{current.subject}</Typography><Typography color="text.secondary" sx={{mt:.5,mb:2}}>{current.from} &lt;{current.email}&gt; · {current.date}</Typography><Divider/><Typography sx={{whiteSpace:'pre-line',lineHeight:1.8,py:2}}>{current.body}</Typography><Stack direction="row" gap={1}><Button variant="outlined" onClick={()=>onDraft(current.email,`Re: ${current.subject}`)}>Reply</Button><Button variant="outlined" onClick={()=>onDraft(current.email,`Fwd: ${current.subject}`)}>Forward</Button><Button onClick={()=>onDraft(current.email,`Re: ${current.subject}`)}>Reply All</Button></Stack><Alert severity="info" sx={{mt:2}}>Email provider is not connected. Replies can be saved as drafts; no email is sent from this demo.</Alert></>:<Typography color="text.secondary">Select an email to read.</Typography>}</Panel></Box>;
}

export function ReportsScreen({data,onExport}:{data:CRMData;onExport:(what:string)=>void}) {
  const [range,setRange]=useState('30');const [detail,setDetail]=useState<'Total Revenue'|'Won Deals'|'Conversion Rate'|'Avg. Deal Size'|null>(null);const [showAll,setShowAll]=useState(false);const [team,setTeam]=useState('All teams');const [performerSort,setPerformerSort]=useState<'revenue'|'wins'>('revenue');const [performerQuery,setPerformerQuery]=useState('');
  const won=data.deals.filter(d=>d.stage==='Won');const visibleRevenue=won.reduce((a,d)=>a+d.amount,0);const revenue=284600+(visibleRevenue-45000);const wonCount=18+(won.length-3);
  const baselines=[{name:'Priya Sharma',wins:7,revenue:88000,sampleWins:1,sampleRevenue:18000},{name:'Dinesh Kumar',wins:3,revenue:42100,sampleWins:1,sampleRevenue:12000},{name:'Rahul Verma',wins:3,revenue:42100,sampleWins:1,sampleRevenue:15000}];
  const performers=data.users.filter(user=>user.status!=='Deactivated').map(user=>{const baseline=baselines.find(person=>person.name===user.name||(user.name==='Dinesh Sarikonda'&&person.name==='Dinesh Kumar'));const deals=won.filter(deal=>deal.owner===user.name||(user.name==='Dinesh Sarikonda'&&deal.owner==='Dinesh Kumar'));const wins=baseline?baseline.wins+deals.length-baseline.sampleWins:deals.length;const earned=baseline?baseline.revenue+deals.reduce((sum,deal)=>sum+deal.amount,0)-baseline.sampleRevenue:deals.reduce((sum,deal)=>sum+deal.amount,0);const weightedOpen=data.deals.filter(deal=>(deal.owner===user.name||(user.name==='Dinesh Sarikonda'&&deal.owner==='Dinesh Kumar'))&&deal.stage!=='Won'&&deal.stage!=='Lost').reduce((sum,deal)=>sum+deal.amount*deal.probability/100,0);return{name:user.name,team:user.team,wins:Math.max(0,wins),revenue:Math.max(0,earned),weightedOpen};}).sort((a,b)=>b[performerSort==='revenue'?'revenue':'wins']-a[performerSort==='revenue'?'revenue':'wins']);
  const shownPerformers=performers.filter(person=>(team==='All teams'||person.team===team)&&person.name.toLowerCase().includes(performerQuery.toLowerCase()));
  const metrics:[string,string,string][]=[['Total Revenue',formatMoney(revenue),'15%'],['Won Deals',String(wonCount),'20%'],['Conversion Rate','16.9%','2.4%'],['Avg. Deal Size',formatMoney(Math.round(revenue/wonCount)),'12%']];
  if(detail)return <ReportDetail metric={detail} data={data} range={range} onRangeChange={setRange} onBack={()=>setDetail(null)} onExport={onExport}/>;
  const tablePerformers=showAll?shownPerformers:shownPerformers.slice(0,3);const maxScale=Math.max(1,...performers.map(person=>person.revenue+person.weightedOpen));
  return <><PageTitle title="Reports & Analytics" actions={<><FormControl size="small"><Select value={range} onChange={event=>setRange(event.target.value)}><MenuItem value="7">Last 7 days</MenuItem><MenuItem value="30">Last 30 days</MenuItem><MenuItem value="90">Last 90 days</MenuItem><MenuItem value="all">All time</MenuItem></Select></FormControl><Button variant="outlined" onClick={()=>{window.print();onExport('printed report')}}>Export PDF</Button><Button variant="outlined" startIcon={<DownloadIcon/>} onClick={()=>{downloadReportXlsx('Summary',shownPerformers);onExport('Excel report downloaded');}}>Export Excel</Button></>}/>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'repeat(2,1fr)',lg:'repeat(4,1fr)'},gap:1.5,mb:1.5}}>{metrics.map(([label,value,delta])=><Metric key={label} label={label} value={value} delta={delta} onClick={()=>setDetail(label as typeof detail & string)}/>)}</Box>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',lg:'1.2fr 1fr'},gap:1.5,mb:1.5}}><Panel sx={{height:340}}><Typography variant="h3" sx={{mb:2}}>Revenue Trend</Typography><ResponsiveContainer width="100%" height={270}><LineChart data={trend}><CartesianGrid stroke="#8A9AAF" opacity={.25} vertical={false}/><XAxis dataKey="month" tick={{fill:'currentColor'}}/><YAxis tick={{fill:'currentColor'}}/><ChartTooltip contentStyle={{backgroundColor:'var(--mui-palette-background-paper)',borderColor:tokens.border,color:'var(--mui-palette-text-primary)'}}/><Line dataKey="won" stroke={tokens.primary500} strokeWidth={3}/><Line dataKey="lost" stroke={tokens.danger} strokeWidth={2}/></LineChart></ResponsiveContainer></Panel><Panel sx={{height:340}}><Typography variant="h3">Deals by Source</Typography><Stack direction="row" alignItems="center" justifyContent="space-evenly" sx={{height:280}}><Box sx={{position:'relative',width:190,height:190}}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={sourceData} dataKey="value" innerRadius={52} outerRadius={82} paddingAngle={3}>{sourceData.map(source=><Cell key={source.name} fill={source.color}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer><Box sx={{position:'absolute',inset:0,display:'grid',placeContent:'center',textAlign:'center',pointerEvents:'none'}}><Typography fontSize={24} fontWeight={700}>42</Typography><Typography variant="caption">Total</Typography></Box></Box><Stack gap={1}>{sourceData.map(source=><Stack key={source.name} direction="row" gap={1} alignItems="center"><Box sx={{width:9,height:9,borderRadius:9,bgcolor:source.color}}/><Typography>{source.name}</Typography><Typography fontWeight={700} sx={{ml:2}}>{source.value}</Typography></Stack>)}</Stack></Stack></Panel></Box>
    <Panel><Stack direction={{xs:'column',md:'row'}} justifyContent="space-between" alignItems={{md:'center'}} gap={1}><Box><Typography variant="h3">Top Performers</Typography><Typography variant="body2" color="text.secondary">Ranked by closed revenue. Projection combines closed revenue and weighted open pipeline.</Typography></Box><Stack direction="row" gap={1} flexWrap="wrap"><TextField size="small" placeholder="Search employee..." value={performerQuery} onChange={event=>setPerformerQuery(event.target.value)}/><FormControl size="small"><Select value={team} onChange={event=>setTeam(event.target.value)}>{['All teams',...Array.from(new Set(data.users.map(user=>user.team)))].map(item=><MenuItem value={item} key={item}>{item}</MenuItem>)}</Select></FormControl><Button variant="outlined" onClick={()=>setShowAll(value=>!value)}>{showAll?'Show top 3':'View all'}</Button><Button onClick={()=>setPerformerSort(value=>value==='revenue'?'wins':'revenue')}>Sort: {performerSort==='revenue'?'Revenue':'Wins'}</Button></Stack></Stack><Box sx={{overflowX:'auto',mt:1}}><Table size="small" sx={{minWidth:760}}><TableHead><TableRow>{['Rank','Employee','Won Deals','Revenue','Projection','Rating'].map(label=><TableCell key={label}>{label}</TableCell>)}</TableRow></TableHead><TableBody>{tablePerformers.map((person,index)=><TableRow key={person.name}><TableCell>#{index+1}</TableCell><TableCell><Stack direction="row" gap={1} alignItems="center"><UserAvatar name={person.name}/><Box><Typography fontWeight={600}>{person.name}</Typography><Typography variant="caption" color="text.secondary">{person.team}</Typography></Box></Stack></TableCell><TableCell>{person.wins}</TableCell><TableCell>{formatMoney(person.revenue)}</TableCell><TableCell sx={{minWidth:190}}><Typography variant="caption">{formatMoney(person.weightedOpen)} weighted pipeline</Typography><Box sx={{height:7,mt:.5,borderRadius:8,bgcolor:'action.selected',overflow:'hidden'}}><Box sx={{height:'100%',width:`${Math.max(2,100*person.revenue/maxScale)}%`,bgcolor:'primary.main',position:'relative','&::after':{content:'""',position:'absolute',right:0,top:0,bottom:0,width:`${Math.max(0,100*person.weightedOpen/Math.max(1,person.revenue+person.weightedOpen))}%`,bgcolor:'success.main'}}}/></Box></TableCell><TableCell><Stack direction="row" alignItems="center" aria-label={`Rank ${index+1}, ${Math.max(1,5-Math.floor(index/10))} stars`}>{Array.from({length:Math.max(1,5-Math.floor(index/10))},(_,star)=><StarIcon key={star} sx={{fontSize:16,color:'#F59E0B'}}/>)}</Stack></TableCell></TableRow>)}</TableBody></Table></Box><Typography variant="caption" color="text.secondary">Only loaded employee and deal records are detailed here; other workspace aggregates remain in the headline totals.</Typography></Panel>
  </>;
}

function ReportDetail({metric,data,range,onRangeChange,onBack,onExport}:{metric:'Total Revenue'|'Won Deals'|'Conversion Rate'|'Avg. Deal Size';data:CRMData;range:string;onRangeChange:(range:string)=>void;onBack:()=>void;onExport:(what:string)=>void}){
  const [owner,setOwner]=useState('All owners');const [selectedDeal,setSelectedDeal]=useState<Deal|null>(null);const [sort,setSort]=useState<{field:'name'|'company'|'date'|'owner'|'amount'|'stage'|'lastContact';direction:'asc'|'desc'}>({field:'date',direction:'desc'});
  const cutoff=()=>{if(range==='all')return '';const date=new Date();date.setDate(date.getDate()-Number(range));return date.toISOString().slice(0,10);};const since=cutoff();
  const leadsMetric=metric==='Conversion Rate';const dealRows=data.deals.filter(deal=>deal.stage==='Won'&&deal.closeDate>=(since||'0000-00-00')&&(owner==='All owners'||deal.owner===owner)).sort((a,b)=>{const field=sort.field==='date'?'closeDate':sort.field==='name'?'title':sort.field==='stage'?'stage':sort.field==='lastContact'?'closeDate':sort.field;const left=String(a[field]??'');const right=String(b[field]??'');return left.localeCompare(right,undefined,{numeric:true})*(sort.direction==='asc'?1:-1);});
  const leadRows=data.leads.filter(lead=>lead.stage==='Won'&&(owner==='All owners'||lead.owner===owner)).sort((a,b)=>String(a[sort.field==='date'?'lastContact':sort.field==='amount'?'name':sort.field==='name'?'name':sort.field]??'').localeCompare(String(b[sort.field==='date'?'lastContact':sort.field==='amount'?'name':sort.field==='name'?'name':sort.field]??''),undefined,{numeric:true})*(sort.direction==='asc'?1:-1));
  const records=leadsMetric?leadRows:dealRows;const exportCsv=()=>{const header=leadsMetric?['Lead','Company','Owner','Stage','Last Contact']:['Deal','Company','Owner','Stage','Close Date','Revenue'];const rows=leadsMetric?leadRows.map(lead=>[lead.name,lead.company,lead.owner,lead.stage,lead.lastContact]):dealRows.map(deal=>[deal.title,deal.company,deal.owner,deal.stage,deal.closeDate,deal.amount]);const csv=[header,...rows].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');const link=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.href=url;link.download=`nexora-${metric.toLowerCase().replaceAll(' ','-')}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);onExport('Filtered report CSV downloaded');};
  const sortHeader=(label:string,field:'name'|'company'|'date'|'owner'|'amount'|'stage'|'lastContact')=><TableCell key={label}><TableSortLabel active={sort.field===field} direction={sort.field===field?sort.direction:'asc'} onClick={()=>setSort(current=>({field,direction:current.field===field&&current.direction==='asc'?'desc':'asc'}))}>{label}</TableSortLabel></TableCell>;
  return <><PageTitle title={metric} subtitle="Filtered report detail" actions={<><Button onClick={onBack}>Back to Reports</Button><FormControl size="small"><Select value={range} onChange={event=>onRangeChange(event.target.value)}><MenuItem value="7">Last 7 days</MenuItem><MenuItem value="30">Last 30 days</MenuItem><MenuItem value="90">Last 90 days</MenuItem><MenuItem value="all">All time</MenuItem></Select></FormControl><FormControl size="small"><Select value={owner} onChange={event=>setOwner(event.target.value)}>{['All owners',...Array.from(new Set(data.leads.map(lead=>lead.owner)))].map(item=><MenuItem key={item} value={item}>{item}</MenuItem>)}</Select></FormControl><Button onClick={exportCsv}>Export CSV</Button><Button onClick={()=>{window.print();onExport('Report opened for PDF printing');}}>Export PDF</Button></>}/><Panel sx={{p:0,overflow:'hidden'}}><Box sx={{overflowX:'auto'}}><Table size="small"><TableHead><TableRow>{leadsMetric?<>{sortHeader('Lead','name')}{sortHeader('Company','company')}{sortHeader('Owner','owner')}{sortHeader('Stage','stage')}{sortHeader('Last Contact','lastContact')}</>:<>{sortHeader('Deal','name')}{sortHeader('Owner','owner')}{sortHeader('Close Date','date')}{sortHeader('Revenue','amount')}</>}</TableRow></TableHead><TableBody>{leadsMetric?leadRows.map(lead=><TableRow key={lead.id}><TableCell>{lead.name}</TableCell><TableCell>{lead.company}</TableCell><TableCell>{lead.owner}</TableCell><TableCell>{lead.stage}</TableCell><TableCell>{lead.lastContact}</TableCell></TableRow>):dealRows.map(deal=><TableRow key={deal.id} hover onClick={()=>setSelectedDeal(deal)} sx={{cursor:'pointer'}}><TableCell>{deal.title}</TableCell><TableCell>{deal.owner}</TableCell><TableCell>{deal.closeDate}</TableCell><TableCell>{formatMoney(deal.amount)}</TableCell></TableRow>)}</TableBody></Table></Box>{!records.length&&<Alert severity="info" sx={{m:1.5}}>No matching named records in this date and owner filter.</Alert>}</Panel><Typography variant="caption" color="text.secondary" sx={{display:'block',mt:1}}>The reference metrics include workspace-wide aggregates. These details list named records loaded in this local demo.</Typography><Dialog open={Boolean(selectedDeal)} onClose={()=>setSelectedDeal(null)} fullWidth maxWidth="sm"><DialogTitle>{selectedDeal?.title} · Revenue detail</DialogTitle><DialogContent dividers>{selectedDeal&&<Stack spacing={.75}><Typography><b>Customer:</b> {selectedDeal.company}</Typography><Typography><b>Revenue:</b> {formatMoney(selectedDeal.amount)}</Typography><Typography><b>Owner:</b> {selectedDeal.owner}</Typography><Typography><b>Closed:</b> {selectedDeal.closeDate}</Typography><Divider sx={{my:1}}/><Typography variant="h3">Related invoices</Typography>{data.invoices.filter(invoice=>invoice.customerCompany===selectedDeal.company).map(invoice=><Box key={invoice.id} sx={{p:1,border:'1px solid',borderColor:'divider',borderRadius:2}}><Typography fontWeight={600}>{invoice.number}</Typography><Typography variant="body2">{invoice.lines.map(line=>`${line.description} × ${line.quantity}`).join(' · ')}</Typography></Box>)}{!data.invoices.some(invoice=>invoice.customerCompany===selectedDeal.company)&&<Typography color="text.secondary">No invoice is linked to this demo deal.</Typography>}</Stack>}</DialogContent><DialogActions><Button onClick={()=>setSelectedDeal(null)}>Close</Button></DialogActions></Dialog></>;
}

function downloadReportXlsx(sheetName:string,performers:{name:string;wins:number;revenue:number;weightedOpen:number}[]){void import('xlsx').then(XLSX=>{const sheet=XLSX.utils.aoa_to_sheet([['Metric','Value'],['Total Revenue',284600],['Won Deals',18],['Conversion Rate','16.9%'],['Average Deal Size',15811],['Employee','Won Deals','Revenue','Weighted Pipeline'],...performers.map(person=>[person.name,person.wins,person.revenue,person.weightedOpen])]);const workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,sheet,sheetName);XLSX.writeFile(workbook,'nexora-report.xlsx');});}
