function auditDate(entry:AuditEntry){
  if(entry.occurredAt){const exact=new Date(entry.occurredAt);if(!Number.isNaN(exact.getTime()))return exact;}
  const now=new Date();if(/^yesterday/i.test(entry.time)){now.setDate(now.getDate()-1);return now;}
  const timeOnly=entry.time.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$/i);
  if(timeOnly){let hour=Number(timeOnly[1]);const minute=Number(timeOnly[2]);if(timeOnly[3]?.toUpperCase()==='PM'&&hour<12)hour+=12;if(timeOnly[3]?.toUpperCase()==='AM'&&hour===12)hour=0;return new Date(now.getFullYear(),now.getMonth(),now.getDate(),hour,minute);}
  const withYear=/\b\d{4}\b/.test(entry.time)?entry.time:`${entry.time}, ${now.getFullYear()}`;const parsed=new Date(withYear);return Number.isNaN(parsed.getTime())?now:parsed;
}

export function AuditScreen({entries,onExport}:{entries:AuditEntry[];onExport:(what:string)=>void}) {
  const [query,setQuery]=useState('');const [user,setUser]=useState('All Users');const [action,setAction]=useState('All Actions');const [period,setPeriod]=useState('All Time');const [month,setMonth]=useState(new Date().toISOString().slice(0,7));
  const now=new Date();const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());const weekStart=new Date(today);weekStart.setDate(today.getDate()-((today.getDay()+6)%7));const monthStart=new Date(now.getFullYear(),now.getMonth(),1);const yearStart=new Date(now.getFullYear(),0,1);
  const rows=entries.filter(entry=>{const date=auditDate(entry);const matchesText=`${entry.user} ${entry.action} ${entry.target} ${entry.type}`.toLowerCase().includes(query.toLowerCase());const matchesUser=user==='All Users'||entry.user===user;const matchesAction=action==='All Actions'||entry.action===action;const matchesDate=period==='Today'?date>=today&&date<new Date(today.getTime()+86400000):period==='This Week'?date>=weekStart&&date<new Date(weekStart.getTime()+7*86400000):period==='This Month'?date>=monthStart&&date<new Date(now.getFullYear(),now.getMonth()+1,1):period==='This Year'?date>=yearStart&&date<new Date(now.getFullYear()+1,0,1):period==='Choose Month'?date.getFullYear()===Number(month.slice(0,4))&&date.getMonth()===Number(month.slice(5))-1:true;return matchesText&&matchesUser&&matchesAction&&matchesDate;}).sort((a,b)=>auditDate(b).getTime()-auditDate(a).getTime());
  const exportFiltered=()=>{const header=['Time','User','Action','Target','Type','Date'];const values=rows.map(entry=>[entry.time,entry.user,entry.action,entry.target,entry.type,auditDate(entry).toLocaleString()]);const csv=[header,...values].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const link=document.createElement('a');link.href=url;link.download=`nexora-audit-${period.toLowerCase().replaceAll(' ','-')}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);onExport(`Downloaded ${rows.length} filtered audit entries`);};
  return <><PageTitle title="Audit Log" subtitle="Review and export recorded workspace actions" actions={<Button variant="contained" startIcon={<DownloadIcon/>} onClick={exportFiltered}>Export filtered log</Button>}/><Stack direction={{xs:'column',md:'row'}} gap={1} sx={{mb:1.5,flexWrap:'wrap'}}><TextField size="small" placeholder="Search actions, users, or targets..." value={query} onChange={event=>setQuery(event.target.value)} sx={{minWidth:260,flex:1}}/><FormControl size="small" sx={{minWidth:145}}><Select value={user} onChange={event=>setUser(event.target.value)}>{['All Users',...Array.from(new Set(entries.map(entry=>entry.user)))].map(value=><MenuItem key={value} value={value}>{value}</MenuItem>)}</Select></FormControl><FormControl size="small" sx={{minWidth:180}}><Select value={action} onChange={event=>setAction(event.target.value)}>{['All Actions',...Array.from(new Set(entries.map(entry=>entry.action)))].map(value=><MenuItem key={value} value={value}>{value}</MenuItem>)}</Select></FormControl><FormControl size="small" sx={{minWidth:145}}><Select value={period} onChange={event=>setPeriod(event.target.value)}>{['All Time','Today','This Week','This Month','This Year','Choose Month'].map(value=><MenuItem key={value} value={value}>{value}</MenuItem>)}</Select></FormControl>{period==='Choose Month'&&<TextField size="small" type="month" value={month} onChange={event=>setMonth(event.target.value)}/>}</Stack><Panel sx={{p:0,overflow:'hidden'}}><Box sx={{overflowX:'auto'}}><Table sx={{minWidth:800}}><TableHead><TableRow>{['Time','User','Action','Target','Type','Date','IP'].map(label=><TableCell key={label}>{label}</TableCell>)}</TableRow></TableHead><TableBody>{rows.map(entry=><TableRow key={entry.id}><TableCell>{entry.time}</TableCell><TableCell>{entry.user}</TableCell><TableCell sx={{fontWeight:600}}>{entry.action}</TableCell><TableCell>{entry.target}</TableCell><TableCell><Chip size="small" label={entry.type} variant="outlined"/></TableCell><TableCell>{auditDate(entry).toLocaleDateString()}</TableCell><TableCell>Local demo</TableCell></TableRow>)}{!rows.length&&<TableRow><TableCell colSpan={7}><Typography color="text.secondary" textAlign="center" sx={{py:3}}>No audit entries match these filters.</Typography></TableCell></TableRow>}</TableBody></Table></Box><Stack direction="row" justifyContent="space-between" sx={{p:1.5}}><Typography variant="body2" color="text.secondary">Showing {rows.length} of {entries.length} audit entries</Typography><Button size="small" onClick={()=>{setQuery('');setUser('All Users');setAction('All Actions');setPeriod('All Time');}}>Clear filters</Button></Stack></Panel></>;
}
export function SettingsScreen({settings,onSave,onNavigate,appearanceMode,onAppearanceChange}:{settings:{company:string;timezone:string;currency:string};onSave:(s:{company:string;timezone:string;currency:string})=>void;onNavigate:(s:string)=>void;appearanceMode:'light'|'dark'|'auto';onAppearanceChange:(mode:'light'|'dark'|'auto')=>void}) {
  const [section,setSection]=useState('Company');const [tab,setTab]=useState('General');const [company,setCompany]=useState(settings.company);const [timezone,setTimezone]=useState(settings.timezone);const [currency,setCurrency]=useState(settings.currency);const [themeMode,setThemeMode]=useState(appearanceMode);const sections=['Profile','Company','Users & Roles','Notifications','Integrations','Pipeline','Custom Fields','Automation','Billing'];
  return <><PageTitle title="Settings"/><Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',md:'240px 1fr'},gap:1.5}}><Panel sx={{alignSelf:'start'}}><Stack>{sections.map(x=><Button key={x} onClick={()=>x==='Users & Roles'?onNavigate(x):setSection(x)} variant={section===x?'contained':'text'} color={section===x?'primary':'inherit'} sx={{justifyContent:'flex-start'}}>{x}</Button>)}</Stack></Panel><Panel>{section==='Company'?<><Typography variant="h3" sx={{mb:1}}>Company Settings</Typography><Tabs value={tab} onChange={(_,v)=>setTab(v)} sx={{mb:1.5}}>{['General','Branding','API'].map(x=><Tab key={x} value={x} label={x}/>)}</Tabs>{tab==='General'?<Stack spacing={1.5} sx={{maxWidth:560}}><TextField label="Company Name" value={company} onChange={e=>setCompany(e.target.value)}/><TextField select label="Time Zone" value={timezone} onChange={e=>setTimezone(e.target.value)}>{['America/New_York','America/Chicago','America/Denver','America/Los_Angeles','UTC'].map(x=><MenuItem key={x} value={x}>{x}</MenuItem>)}</TextField><TextField select label="Currency" value={currency} onChange={e=>setCurrency(e.target.value)}>{['USD – US Dollar','EUR – Euro','GBP – British Pound','CAD – Canadian Dollar'].map(x=><MenuItem key={x} value={x}>{x}</MenuItem>)}</TextField><Typography variant="caption" color="text.secondary">Company Logo</Typography><Stack direction="row" gap={1} alignItems="center"><Avatar sx={{bgcolor:'primary.main'}}>N</Avatar><Button variant="outlined" component="label">Upload Logo<input hidden type="file" accept="image/*" onChange={e=>e.target.files?.[0]&&window.alert('Logo selected. Save to apply it to this browser demo.')}/></Button></Stack><Button variant="contained" sx={{alignSelf:'start'}} onClick={()=>onSave({company,timezone,currency})}>Save Changes</Button></Stack>:tab==='Branding'?<Stack spacing={2}><Alert severity="info">Brand colors and company logo are preview settings in this local demo.</Alert><TextField label="Primary color" type="color" defaultValue="#2563EB"/><Button variant="contained" onClick={()=>window.alert('Branding preferences saved in this browser demo.')}>Save Branding</Button></Stack>:<Alert severity="warning">API credentials are managed on the server and are not shown in the browser.</Alert>}</>:section==='Profile'?<Stack spacing={1.5} sx={{maxWidth:560}}><Typography variant="h3">My Profile</Typography><TextField label="Full name" defaultValue="Dinesh Sarikonda"/><TextField label="Work email" defaultValue="dinesh@nexora.com"/><TextField label="Phone" defaultValue="+1 415 555 0100"/><Divider/><Typography variant="h3">Appearance</Typography><Typography color="text.secondary">Choose a theme, or follow your device’s day and night appearance.</Typography><TextField select label="Theme" value={themeMode} onChange={e=>{const value=e.target.value as 'light'|'dark'|'auto';setThemeMode(value);onAppearanceChange(value);}}>{[['auto','Auto (follow device)'],['light','Light'],['dark','Dark']].map(([value,label])=><MenuItem key={value} value={value}>{label}</MenuItem>)}</TextField><Button variant="contained" sx={{alignSelf:'start'}} onClick={()=>window.alert('Profile preferences saved in this demo.')}>Save Profile</Button></Stack>:section==='Pipeline'?<><Typography variant="h3">Pipeline Stages</Typography><Stack spacing={1} sx={{mt:1.5}}>{stages.map((s,i)=><Stack key={s} direction="row" alignItems="center" justifyContent="space-between" sx={{p:1,border:`1px solid ${tokens.border}`,borderRadius:2}}><Stack direction="row" gap={1} alignItems="center"><Typography>{i+1}.</Typography><StageChip stage={s}/></Stack><IconButton aria-label={`More actions for ${s}`} onClick={()=>window.alert(`${s} stage settings are ready to edit when pipeline persistence is connected.`)}><MoreHorizIcon/></IconButton></Stack>)}</Stack><Button sx={{mt:1}} startIcon={<AddIcon/>} onClick={()=>window.alert('Custom pipeline stage editor is available in the next data configuration step.')}>Add Stage</Button></>:<><Typography variant="h3">{section}</Typography><Alert severity="info" sx={{mt:1}}>Configure {section.toLowerCase()} when a live CRM backend is connected. The current demo keeps data in this browser only.</Alert>{section==='Integrations'&&<Stack direction="row" gap={1} sx={{mt:1}}>{['Email provider','Calendar sync','WhatsApp'].map(x=><Button key={x} variant="outlined" onClick={()=>window.alert(`${x} integration requires service credentials.`)}>Connect {x}</Button>)}</Stack>}</>}</Panel></Box></>;
}

export function ImportScreen({onImport}:{onImport:(rows:Partial<Lead>[])=>void}) {
  const [rows,setRows]=useState<Partial<Lead>[]>([]);const [filename,setFilename]=useState('');const [error,setError]=useState('');const [step,setStep]=useState(1);
  const parseFile=async(file:File)=>{setError('');setFilename(file.name);setRows([]);if(file.size>10*1024*1024){setError('The selected file exceeds the 10 MB import limit.');return;}if(!/\.(xlsx|xls|csv)$/i.test(file.name)){setError('Choose an .xlsx, .xls, or .csv file.');return;}try{const XLSX=await import('xlsx');const bytes=await file.arrayBuffer();const workbook=XLSX.read(bytes,{type:'array'});const first=workbook.Sheets[workbook.SheetNames[0]];const raw=XLSX.utils.sheet_to_json<Record<string,unknown>>(first,{defval:'',blankrows:false}).slice(0,50001);if(raw.length>50000){setError('The selected file exceeds the 50,000 row import limit.');return;}const normalized=raw.map((r,index)=>{const values=Object.fromEntries(Object.entries(r).map(([k,v])=>[k.trim().toLowerCase().replaceAll(/[^a-z]/g,''),String(v??'').trim()]));const get=(...keys:string[])=>keys.map(k=>values[k]).find(Boolean)??'';const email=get('email','mail');return {id:`import-${Date.now()}-${index}`,name:get('name','fullname'),company:get('company'),email:/^\S+@\S+\.\S+$/.test(email)?email:'',phone:get('phone','mobile'),stage:'New' as const,source:get('source')||'Import',owner:'Dinesh Kumar',lastContact:'Just now',location:get('location','region'),priority:'Medium' as const,tags:[],nextFollowUp:'No follow-up scheduled',activity:[]};}).filter(r=>r.name||r.email);setRows(normalized);setStep(2);if(!normalized.length)setError('No rows with a name or valid email were found in that workbook.');}catch{setError('Could not read that file. Use a valid .xlsx, .xls, or .csv workbook.');}};
  return <><PageTitle title="Import Data from Excel" subtitle={`${filename||'Choose a spreadsheet'} · ${rows.length} preview rows`} actions={<><Button variant="outlined" onClick={async()=>{const XLSX=await import('xlsx');const ws=XLSX.utils.aoa_to_sheet([['Full Name','Phone','Email','Company','Source'],['Alex Smith','+1 415 555 0100','alex@example.com','Example Inc','Website']]);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Leads');XLSX.writeFile(wb,'nexora-leads-template.xlsx');}}>Download Template</Button><Button variant="contained" disabled={!rows.length} onClick={()=>{onImport(rows);setRows([]);setStep(3);}}>Start Import</Button></>}/><Panel sx={{mb:1.5}}><Stack direction="row" gap={3} alignItems="center" flexWrap="wrap">{['1  Upload','2  Map columns','3  Preview','4  Import'].map((s,i)=><Typography key={s} fontWeight={step===i+1?700:500} color={step===i+1?'primary.main':'text.secondary'}>{s}</Typography>)}</Stack></Panel><Stack direction="row" gap={1.5} sx={{mb:1.5}}><Metric label="Valid rows" value={String(rows.filter(r=>r.name&&r.email).length)} color={tokens.success}/><Metric label="Duplicates" value="0" color={tokens.warning}/><Metric label="Errors" value={String(rows.filter(r=>!r.email).length)} color={tokens.danger}/><Metric label="Default owner" value="Dinesh Kumar"/></Stack>{error&&<Alert severity="error" sx={{mb:1}}>{error}</Alert>}<Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',xl:'1fr 1.3fr'},gap:1.5}}><Panel><Typography variant="h3">Upload and column mapping</Typography><Button component="label" variant="outlined" sx={{mt:2}}>Choose Excel or CSV file<input type="file" hidden accept=".xlsx,.xls,.csv" onChange={e=>e.target.files?.[0]&&parseFile(e.target.files[0])}/></Button><Typography color="text.secondary" sx={{mt:1}}>Supports .xlsx, .xls, and .csv. Matching rows are added to this browser's demo dataset.</Typography><Divider sx={{my:2}}/><Stack spacing={1}>{[['Full Name','name'],['Phone','phone'],['Email','email'],['Company','company'],['Source','source']].map(([x,y])=><Stack key={x} direction="row" alignItems="center" justifyContent="space-between" sx={{py:1,borderBottom:`1px solid ${tokens.border}`}}><Typography>{x}</Typography><Typography color="text.secondary">→ {y}</Typography><Chip size="small" label="Matched" color="success"/></Stack>)}</Stack></Panel><Panel><Typography variant="h3">Preview (first rows)</Typography>{rows.length?<Box sx={{overflowX:'auto'}}><Table size="small"><TableHead><TableRow>{['Name','Phone','Email','Company','Result'].map(x=><TableCell key={x}>{x}</TableCell>)}</TableRow></TableHead><TableBody>{rows.slice(0,8).map((r,i)=><TableRow key={i}><TableCell>{r.name}</TableCell><TableCell>{r.phone}</TableCell><TableCell>{r.email}</TableCell><TableCell>{r.company}</TableCell><TableCell><Chip size="small" label={r.name&&r.email?'New':'Missing email'} color={r.name&&r.email?'success':'error'}/></TableCell></TableRow>)}</TableBody></Table></Box>:<Box sx={{py:6,textAlign:'center',color:'text.secondary'}}>Select a spreadsheet to preview its rows.</Box>}</Panel></Box></>;
}

export function LeadsScreen({leads,onSelect,onAdd,onImport,onUpdateStage,onBulkStage}: {leads:Lead[];onSelect:(l:Lead)=>void;onAdd:()=>void;onImport:()=>void;onUpdateStage:(id:string,s:Stage)=>void;onBulkStage:(ids:string[],s:Stage)=>void}) {
  const [search,setSearch]=useState(''); const [stage,setStage]=useState('All Stages'); const [source,setSource]=useState('All Sources'); const [owner,setOwner]=useState('All Owners'); const [priority,setPriority]=useState('All Priorities');const [selected,setSelected]=useState<string[]>([]);const [bulkStage,setBulkStage]=useState<Stage>('Qualified');const [sort,setSort]=useState<{field:keyof Lead;direction:'asc'|'desc'}>({field:'name',direction:'asc'});
  const rows=leads.filter(l=>(`${l.name} ${l.company} ${l.email} ${l.phone} ${l.location} ${l.source} ${l.tags.join(' ')}`.toLowerCase().includes(search.toLowerCase()))&&(stage==='All Stages'||l.stage===stage)&&(source==='All Sources'||l.source===source)&&(owner==='All Owners'||l.owner===owner)&&(priority==='All Priorities'||l.priority===priority)).sort((a,b)=>{const left=String(a[sort.field]??'');const right=String(b[sort.field]??'');return left.localeCompare(right,undefined,{numeric:true,sensitivity:'base'})*(sort.direction==='asc'?1:-1);});
  const sortedHeader=(label:string,field:keyof Lead)=><TableCell key={label} sx={{color:'text.secondary',fontWeight:600,whiteSpace:'nowrap'}}><TableSortLabel active={sort.field===field} direction={sort.field===field?sort.direction:'asc'} onClick={()=>setSort(current=>({field,direction:current.field===field&&current.direction==='asc'?'desc':'asc'}))}>{label}</TableSortLabel></TableCell>;
  return <><PageTitle title="Leads" actions={<><Button variant="outlined" onClick={onImport}>Import from Excel</Button><Button variant="contained" startIcon={<AddIcon/>} onClick={onAdd}>Add Lead</Button></>}/>
    <Stack direction={{xs:'column',md:'row'}} gap={1.25} sx={{mb:1.75}}><TextField size="small" placeholder="Search leads, email, phone, tags..." value={search} onChange={e=>setSearch(e.target.value)} sx={{minWidth:{md:300},flex:1}} InputProps={{startAdornment:<InputAdornment position="start"><SearchIcon fontSize="small"/></InputAdornment>}}/>{[['stage',stage,setStage,['All Stages',...stages,'Lost']],['source',source,setSource,['All Sources',...Array.from(new Set(leads.map(l=>l.source))) ]],['owner',owner,setOwner,['All Owners',...Array.from(new Set(leads.map(l=>l.owner))) ]],['priority',priority,setPriority,['All Priorities','High','Medium','Low']]].map(([key,val,set,opts])=><FormControl size="small" key={String(key)} sx={{minWidth:130}}><Select value={val as string} onChange={e=>(set as (x:string)=>void)(e.target.value)}>{(opts as string[]).map(o=><MenuItem key={o} value={o}>{o}</MenuItem>)}</Select></FormControl>)}{(search||stage!=='All Stages'||source!=='All Sources'||owner!=='All Owners'||priority!=='All Priorities')&&<Button onClick={()=>{setSearch('');setStage('All Stages');setSource('All Sources');setOwner('All Owners');setPriority('All Priorities');}}>Clear filters</Button>}</Stack>
    {selected.length>0&&<Stack direction="row" gap={1} alignItems="center" sx={{mb:1}}><Typography variant="body2">{selected.length} selected</Typography><FormControl size="small" sx={{minWidth:150}}><Select value={bulkStage} onChange={e=>setBulkStage(e.target.value as Stage)}>{stages.concat('Lost').map(s=><MenuItem key={s} value={s}>{s}</MenuItem>)}</Select></FormControl><Button variant="outlined" onClick={()=>{onBulkStage(selected,bulkStage);setSelected([])}}>Apply stage</Button><Button onClick={()=>setSelected([])}>Clear</Button></Stack>}
    <Panel sx={{p:0,overflow:'hidden'}}><Box sx={{overflowX:'auto'}}><Table size="small" sx={{minWidth:930}}><TableHead><TableRow><TableCell padding="checkbox"><Checkbox size="small" checked={rows.length>0&&rows.every(r=>selected.includes(r.id))} indeterminate={selected.length>0&&!rows.every(r=>selected.includes(r.id))} onChange={e=>setSelected(e.target.checked?Array.from(new Set([...selected,...rows.map(r=>r.id)])):selected.filter(id=>!rows.some(r=>r.id===id)))}/></TableCell>{sortedHeader('Name','name')}{sortedHeader('Company','company')}{sortedHeader('Email','email')}{sortedHeader('Stage','stage')}{sortedHeader('Source','source')}{sortedHeader('Owner','owner')}{sortedHeader('Last Contact','lastContact')}</TableRow></TableHead><TableBody>{rows.map(l=><TableRow hover key={l.id} onClick={()=>onSelect(l)} sx={{cursor:'pointer'}}><TableCell padding="checkbox"><Checkbox size="small" checked={selected.includes(l.id)} onClick={e=>e.stopPropagation()} onChange={e=>setSelected(s=>e.target.checked?[...s,l.id]:s.filter(x=>x!==l.id))}/></TableCell><TableCell><Stack direction="row" alignItems="center" gap={1}><UserAvatar name={l.name} size={32}/><Typography fontWeight={600}>{l.name}</Typography></Stack></TableCell><TableCell>{l.company}</TableCell><TableCell>{l.email}</TableCell><TableCell onClick={e=>e.stopPropagation()}><Select variant="standard" disableUnderline value={l.stage} onChange={e=>onUpdateStage(l.id,e.target.value as Stage)} sx={{minWidth:100}}>{['New','Contacted','Qualified','Proposal','Won','Lost'].map(s=><MenuItem key={s} value={s}>{s}</MenuItem>)}</Select></TableCell><TableCell>{l.source}</TableCell><TableCell>{l.owner}</TableCell><TableCell>{l.lastContact}</TableCell></TableRow>)}</TableBody></Table></Box><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{px:2,py:1.5}}><Typography variant="body2" color="text.secondary">Showing {rows.length} named demo records · {248+Math.max(0,leads.length-7)} total workspace leads in the reference</Typography><Typography variant="body2" color="text.secondary">Only loaded records can be viewed or changed</Typography></Stack></Panel>
  </>;
}

export function LeadProfile({lead,tickets,emails,invoices,onBack,onEdit,onNote,onCreateDeal,onShare,onAction,onAddTicket,onEditTicket,onAddTag,onDeleteTag,onCreateInvoice,onInvoiceExport}: {lead:Lead;tickets:Ticket[];emails:EmailItem[];invoices:Invoice[];onBack:()=>void;onEdit:()=>void;onNote:()=>void;onCreateDeal:()=>void;onShare:()=>void;onAction:(s:string)=>void;onAddTicket:()=>void;onEditTicket:(ticket:Ticket)=>void;onAddTag:(tag:string)=>void;onDeleteTag:(tag:string)=>void;onCreateInvoice:()=>void;onInvoiceExport:(invoice:Invoice,format:'pdf'|'word')=>void}) {
  const [tab,setTab]=useState('Overview');
  const [tagDraft,setTagDraft]=useState('');
  const [ticketSearch,setTicketSearch]=useState('');
  const [selectedTicket,setSelectedTicket]=useState<Ticket|null>(null);
  const leadTickets=tickets.filter(ticket=>ticket.leadId===lead.id);
  const visibleTickets=leadTickets.filter(ticket=>`${ticket.ticketNumber} ${ticket.title} ${ticket.description}`.toLowerCase().includes(ticketSearch.toLowerCase()));
  const leadEmails=emails.filter(email=>email.leadId===lead.id||email.email.toLowerCase()===lead.email.toLowerCase());
  const leadInvoices=invoices.filter(invoice=>invoice.leadId===lead.id);
  const quick=(label:string,icon:React.ReactNode)=> <Button key={label} size="small" variant="outlined" startIcon={icon} onClick={()=>onAction(label)}>{label}</Button>;
  const tabs=['Overview',`Activity Log (${lead.activity.length})`,`Tickets (${leadTickets.length})`,`Emails (${leadEmails.length})`,'Files',`Related (${leadInvoices.length})`];
  return <>
    <Stack direction={{xs:'column',md:'row'}} alignItems={{xs:'stretch',md:'center'}} justifyContent="space-between" gap={1.5} sx={{mb:1.25}}><Stack direction="row" alignItems="center" gap={1.5}><UserAvatar name={lead.name} size={52}/><Box><Stack direction="row" gap={1} alignItems="center" flexWrap="wrap"><Typography variant="h1">{lead.name}</Typography><StageChip stage={lead.stage}/><PriorityChip priority={lead.priority}/></Stack><Typography color="text.secondary">{lead.company}</Typography></Box></Stack><Stack direction="row" gap={.75} flexWrap="wrap"><Button size="small" variant="outlined" onClick={onBack}>Back to Leads</Button><Button size="small" variant="outlined" onClick={onEdit}>Edit</Button><Button size="small" variant="outlined" onClick={onNote}>Add Note</Button><Button size="small" variant="contained" onClick={onCreateDeal}>Create Deal</Button><Button size="small" variant="outlined" startIcon={<ShareOutlinedIcon/>} onClick={onShare}>Share</Button></Stack></Stack>
    <Tabs value={tab} onChange={(_,v)=>setTab(v)} sx={{mb:1.5,borderBottom:`1px solid ${tokens.border}`}} variant="scrollable" scrollButtons="auto">{tabs.map(t=><Tab key={t} value={t} label={t}/>)}</Tabs>
    {tab==='Overview'?<Box sx={{display:'grid',gridTemplateColumns:{xs:'1fr',xl:'1fr 1.45fr 1fr'},gap:1.5}}>
      <Stack gap={1.5}><Panel><Typography variant="h3" sx={{mb:1.5}}>Contact Information</Typography><Typography variant="caption" color="text.secondary">Email</Typography><Typography>{lead.email}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1}}>Phone</Typography><Typography>{lead.phone}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1}}>Location</Typography><Typography>{lead.location}</Typography><Stack direction="row" gap={.75} flexWrap="wrap" sx={{mt:1.5}}>{quick('Call',<PhoneOutlinedIcon/>)}{quick('Email',<MailOutlineIcon/>)}{quick('WhatsApp',<WhatsAppIcon/>)}</Stack></Panel><Panel><Typography variant="h3" sx={{mb:1}}>Lead Details</Typography><Typography variant="caption" color="text.secondary">Source</Typography><Typography>{lead.source}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1}}>Assigned To</Typography><Typography>{lead.owner}</Typography><Typography variant="caption" color="text.secondary" display="block" sx={{mt:1}}>Created On</Typography><Typography>Oct 12, 2026</Typography></Panel></Stack>
      <Panel><Typography variant="h3" sx={{mb:1.5}}>Recent Activity</Typography><Stack spacing={1.5}>{lead.activity.map((a,i)=><Stack key={`${a.title}-${i}`} direction="row" gap={1.25}><Box sx={{width:3,bgcolor:'#DCE6F4',borderRadius:4}}/><Box><Typography fontWeight={600}>{a.title}</Typography><Typography color="text.secondary">{a.detail}</Typography></Box></Stack>)}</Stack></Panel>
      <Stack gap={1.5}><Panel><Typography variant="h3">Linked Deals</Typography><Stack direction="row" alignItems="center" justifyContent="space-between" sx={{mt:1.5}}><Box><Typography fontWeight={600}>{lead.company} – Enterprise</Typography><Typography variant="body2">$12,000 · {lead.stage}</Typography></Box><Typography fontWeight={600}>70%</Typography></Stack><Box sx={{height:7,bgcolor:'#DBEAFE',borderRadius:9,mt:1}}><Box sx={{height:7,width:'70%',bgcolor:tokens.primary600,borderRadius:9}}/></Box></Panel><Panel><Typography variant="h3">Next Follow Up</Typography><Typography color="text.secondary" sx={{mt:1}}>{lead.nextFollowUp}</Typography></Panel><Panel><Typography variant="h3">Tags</Typography><Stack direction="row" gap={.5} flexWrap="wrap" sx={{mt:1}}>{lead.tags.map(t=><Chip key={t} size="small" label={t} color="primary" variant="outlined" onDelete={()=>onDeleteTag(t)}/>)}</Stack><Stack direction="row" gap={.75} sx={{mt:1}}><TextField size="small" label="Add tag" value={tagDraft} onChange={event=>setTagDraft(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&tagDraft.trim()){event.preventDefault();onAddTag(tagDraft.trim());setTagDraft('');}}}/><Button onClick={()=>{if(tagDraft.trim()){onAddTag(tagDraft.trim());setTagDraft('');}}}>Add</Button></Stack></Panel><Panel><Typography variant="h3">Quick Actions</Typography><Stack direction="row" gap={.5} flexWrap="wrap" sx={{mt:1}}>{['Call','Email','Task','Ticket'].map(x=><Button size="small" key={x} onClick={()=>x==='Ticket'?onAddTicket():onAction(x)}>{x}</Button>)}</Stack></Panel></Stack>
    </Box>:tab.startsWith('Activity Log')?<Panel><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="h3">Activity Log</Typography><Button onClick={onNote}>Add Note</Button></Stack><Stack spacing={1.5} sx={{mt:2}}>{lead.activity.map((item,index)=><Stack key={`${item.title}-${index}`} direction="row" gap={1.25}><Box sx={{width:3,bgcolor:tokens.primary500,borderRadius:4}}/><Box><Typography fontWeight={600}>{item.title}</Typography><Typography color="text.secondary">{item.detail}</Typography><Typography variant="caption" color="text.secondary">{item.time}</Typography></Box></Stack>)}{!lead.activity.length&&<Typography color="text.secondary">No activity has been recorded yet.</Typography>}</Stack></Panel>:tab.startsWith('Tickets')?<Panel><Stack direction={{xs:'column',sm:'row'}} justifyContent="space-between" alignItems={{sm:'center'}} gap={1}><Box><Typography variant="h3">Tickets</Typography><Typography variant="body2" color="text.secondary">Search by the unique ticket number, title, or details.</Typography></Box><Button variant="contained" onClick={onAddTicket}>Create Ticket</Button></Stack><TextField size="small" fullWidth placeholder="Search ticket number or details..." value={ticketSearch} onChange={event=>setTicketSearch(event.target.value)} sx={{mt:1.5}}/><Stack spacing={1} sx={{mt:1.5}}>{visibleTickets.map(ticket=><Button key={ticket.id} onClick={()=>setSelectedTicket(ticket)} sx={{p:1.5,display:'block',textAlign:'left',textTransform:'none',color:'text.primary',border:`1px solid ${tokens.border}`,borderRadius:2}}><Stack direction="row" justifyContent="space-between" gap={1}><Box><Typography fontWeight={700}>{ticket.ticketNumber} · {ticket.title}</Typography><Typography variant="body2" color="text.secondary">{ticket.description}</Typography></Box><Chip size="small" label={ticket.status} color={ticket.status==='Resolved'?'success':ticket.status==='In Progress'?'primary':'warning'}/></Stack><Typography variant="caption" color="text.secondary">{ticket.priority} priority · {ticket.dueAt?`Due ${new Date(ticket.dueAt).toLocaleString()}`:'No due date'} · Created {ticket.createdAt}</Typography></Button>)}{!visibleTickets.length&&<Alert severity="info">{ticketSearch?'No tickets match that search.':'No tickets for this lead yet. Create one to track a customer request.'}</Alert>}</Stack></Panel>:tab.startsWith('Emails')?<Panel><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="h3">Emails</Typography><Button onClick={()=>onAction('Email')}>Compose</Button></Stack><Stack spacing={1} sx={{mt:2}}>{leadEmails.map(email=><Box key={email.id} sx={{p:1.5,border:`1px solid ${tokens.border}`,borderRadius:2}}><Typography fontWeight={600}>{email.subject}</Typography><Typography variant="body2" color="text.secondary">{email.from} · {email.date}</Typography><Typography sx={{mt:.75,whiteSpace:'pre-line'}}>{email.body}</Typography></Box>)}{!leadEmails.length&&<Alert severity="info">No email history is stored for this lead. Compose saves a draft in the Email section; sending requires a connected email provider.</Alert>}</Stack></Panel>:tab==='Files'?<Panel><Typography variant="h3">Files</Typography><Typography color="text.secondary" sx={{mt:1}}>No files are attached to this lead. File storage needs a configured private Supabase Storage bucket.</Typography></Panel>:<Panel><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="h3">Related Records</Typography><Button variant="contained" onClick={onCreateInvoice}>Create Invoice</Button></Stack><Typography variant="subtitle2" sx={{mt:2}}>Linked Deals</Typography><Box sx={{p:1.5,border:`1px solid ${tokens.border}`,borderRadius:2,mt:.75}}><Typography fontWeight={600}>{lead.company} – Enterprise</Typography><Typography variant="body2" color="text.secondary">$12,000 · {lead.stage}</Typography></Box><Typography variant="subtitle2" sx={{mt:2}}>Invoices</Typography><Stack spacing={1} sx={{mt:.75}}>{leadInvoices.map(invoice=><Box key={invoice.id} sx={{p:1.5,border:`1px solid ${tokens.border}`,borderRadius:2}}><Stack direction={{xs:'column',sm:'row'}} justifyContent="space-between" gap={1}><Box><Typography fontWeight={600}>{invoice.number}</Typography><Typography variant="body2" color="text.secondary">{invoice.date} · {invoice.lines.length} line items · {invoice.taxRate}% tax</Typography></Box><Stack direction="row" gap={.5}><Button size="small" onClick={()=>onInvoiceExport(invoice,'pdf')}>PDF</Button><Button size="small" onClick={()=>onInvoiceExport(invoice,'word')}>Word</Button></Stack></Stack></Box>)}{!leadInvoices.length&&<Alert severity="info">No invoices have been created for this lead.</Alert>}</Stack></Panel>}
    <Dialog open={Boolean(selectedTicket)} onClose={()=>setSelectedTicket(null)} fullWidth maxWidth="sm"><DialogTitle>{selectedTicket?.ticketNumber} · {selectedTicket?.title}</DialogTitle><DialogContent dividers>{selectedTicket&&<Stack spacing={1}><Typography color="text.secondary">{selectedTicket.description}</Typography><Divider sx={{my:1}}/><Typography><b>Status:</b> {selectedTicket.status}</Typography><Typography><b>Priority:</b> {selectedTicket.priority}</Typography><Typography><b>Due:</b> {selectedTicket.dueAt?new Date(selectedTicket.dueAt).toLocaleString():'No due date set'}</Typography><Typography><b>Created:</b> {selectedTicket.createdAt}</Typography></Stack>}</DialogContent><DialogActions><Button onClick={()=>setSelectedTicket(null)}>Close</Button><Button variant="contained" onClick={()=>{if(selectedTicket)onEditTicket(selectedTicket);setSelectedTicket(null);}}>Edit ticket</Button></DialogActions></Dialog>  </>;
}

export function DealsScreen({deals,onAdd,onMove,onSelect}: {deals:Deal[];onAdd:()=>void;onMove:(id:string,s:Stage)=>void;onSelect?:(d:Deal)=>void}) {
  const [query,setQuery]=useState(''); const [owner,setOwner]=useState('All'); const [dragId,setDragId]=useState('');const [selectedDeal,setSelectedDeal]=useState<Deal|null>(null);const theme=useTheme();const dark=theme.palette.mode==='dark';
  const filtered=deals.filter(d=>(`${d.company} ${d.title}`.toLowerCase().includes(query.toLowerCase()))&&(owner==='All'||d.owner===owner));
  const sampleAmount:Record<string,number>={New:26000,Contacted:26000,Qualified:36500,Proposal:40500,Won:45000};
  const visibleTotal=deals.reduce((a,d)=>a+d.amount,0);const visibleWeighted=deals.reduce((a,d)=>a+d.amount*d.probability/100,0);
  const totalPipeline=342000+(visibleTotal-174000);const weightedForecast=209400+(visibleWeighted-109750);
  return <><PageTitle title="Deals" actions={<><TextField size="small" placeholder="Search deals..." value={query} onChange={e=>setQuery(e.target.value)}/><FormControl size="small" sx={{minWidth:130}}><Select value={owner} onChange={e=>setOwner(e.target.value)}><MenuItem value="All">Owner: All</MenuItem>{Array.from(new Set(deals.map(d=>d.owner))).map(o=><MenuItem key={o} value={o}>{o}</MenuItem>)}</Select></FormControl><Button variant="contained" startIcon={<AddIcon/>} onClick={onAdd}>Add Deal</Button></>}/>
    <Box sx={{display:'grid',gridTemplateColumns:{xs:'repeat(5,minmax(240px,1fr))',lg:'repeat(5,minmax(0,1fr))'},gap:1.25,overflowX:'auto',pb:1}}>{stages.map(s=>{const ds=filtered.filter(d=>d.stage===s);const all=deals.filter(d=>d.stage===s);const sum=all.reduce((a,d)=>a+d.amount,0);const aggregate=stageTotals[s].amount+(sum-sampleAmount[s]);const count=stageTotals[s].count+(all.length-3);return <Box key={s} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(dragId)onMove(dragId,s);setDragId('');}} sx={{bgcolor:dark?'#16253A':'#EEF3FA',borderTop:`3px solid ${tokens[s==='New'?'primary500':s==='Contacted'?'teal':s==='Qualified'?'purple':s==='Proposal'?'warning':'success']}`,borderRadius:2.5,p:1.25,minHeight:420}}><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography fontWeight={700}>{s} ({Math.max(0,count)})</Typography><MoreHorizIcon fontSize="small" color="disabled"/></Stack><Typography variant="body2" color="text.secondary" sx={{mb:1.25}}>{formatMoney(aggregate)}</Typography><Stack gap={1}>{ds.map(d=><Panel key={d.id} sx={{p:1.25,cursor:'pointer'}} draggable onDragStart={()=>setDragId(d.id)} onClick={()=>{setSelectedDeal(d);onSelect?.(d);}}><Typography fontWeight={600}>{d.company}</Typography><Stack direction="row" justifyContent="space-between" alignItems="center"><Typography variant="body2">{formatMoney(d.amount)}</Typography><Typography variant="body2" color="text.secondary">{d.owner.split(' ')[0]}</Typography></Stack><Stack direction="row" justifyContent="space-between" alignItems="center" sx={{mt:1}}><Typography variant="caption" color="text.secondary">{d.probability}% chance</Typography><Tooltip title="Move to next stage"><IconButton size="small" onClick={e=>{e.stopPropagation();const i=stages.indexOf(s);onMove(d.id,stages[Math.min(i+1,stages.length-1)]);}}><AddIcon fontSize="small"/></IconButton></Tooltip></Stack></Panel>)}</Stack><Button size="small" fullWidth startIcon={<AddIcon/>} onClick={onAdd} sx={{mt:1}}>Add Deal</Button></Box>})}</Box>
    <Dialog open={Boolean(selectedDeal)} onClose={()=>setSelectedDeal(null)} fullWidth maxWidth="xs"><DialogTitle>{selectedDeal?.title}</DialogTitle><DialogContent dividers>{selectedDeal&&<Stack spacing={.75}><Typography color="text.secondary">{selectedDeal.company}</Typography><Divider sx={{my:1}}/><Typography><b>Amount:</b> {formatMoney(selectedDeal.amount)}</Typography><Typography><b>Stage:</b> {selectedDeal.stage}</Typography><Typography><b>Owner:</b> {selectedDeal.owner}</Typography><Typography><b>Probability:</b> {selectedDeal.probability}%</Typography><Typography><b>Expected close:</b> {selectedDeal.closeDate}</Typography></Stack>}</DialogContent><DialogActions><Button onClick={()=>setSelectedDeal(null)}>Close</Button></DialogActions></Dialog>
    <Stack direction="row" justifyContent="space-between" sx={{mt:1}}><Typography color="text.secondary">Total Pipeline: {formatMoney(totalPipeline)}</Typography><Typography color="text.secondary">Weighted Forecast: {formatMoney(weightedForecast)}</Typography></Stack>
  </>;
}
